INSERT INTO `master_policy_feature_template_fields` VALUES (1,'Feature Identifier','Please Enter Template Name',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'','0',NULL,NULL),(2,'Room Rent Limit','Room Rent Limit',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'When You get get hospitalized for an ailment the cost of the room allotted to you\n                                   as per the category you choose is room rent. This include the bed charges, Nursing charges\n                                   and doctor visit charges. In some policies surgeon fees is also clubbed under room rent Food \n                                   ordered for anyone apart from patient is not covered under room rent.','5',NULL,NULL),(3,'ICU Limit','Enter ICU Limit',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'When a person admitted in the intensive care unit (ICU) the daily charges for the same will be\n                                  payable, this would also inculde operation theater charges in some cases.','5',NULL,NULL),(4,'Proportionate deduction on exceeding room rent','Enter Proportionate deduction on exceeding room rent',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'In Case a person opts for a room which is higher that the limit prescribed under the room rent \n                                   limit of the policy. Deductions will be applied to other heads like doctor visit, nursing charges \n                                   etc as well.','5',NULL,NULL),(5,'Existing Disease Waiting Period','Enter Existing Disease Waiting Period',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'Prior to buying health insurance policy if you are suffering from an ailment which is natural or \n                                   arises due to accidental and if you are taking any medication for any health condition that would \n                                   be termed as a pre existing diease. While buying health insurance it is recommended to declare any \n                                   such ailments or past hospitalizations of past due. Incase you don\'t declare and it is reviled during \n                                   your hospitalization claim will be rejected.','12',NULL,NULL),(6,'Ailment wise waiting period','Enter Ailment wise waiting period',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'In a policy, Waiting period would be applicable for certain ailments as per the prescribed terms and \n                                   conditions. Claims for such ailments will be payable after the completion of witing period.','12',NULL,NULL),(7,'Pre & post natal Expenses','Enter Pre & post natal Expenses',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'Pre and post-nadal expenses would mean costs pertaining to utrasound, regular checkups, doctor\'s \n                                   consultaion fee, medicines and so on. These are similar to pre-and post- Hospitalization expenses \n                                   that are admissible under a standard health insurance policy.','2',NULL,NULL),(8,'Ailment wise capping','Enter Ailment wise capping',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'Under the Policy claims for certain policies is limited prescribed as per terms of the policy.','12',NULL,NULL),(9,'Internal congenital disease','Enter Internal congenital disease',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'Disability/defect to an internal body organ in the body from the birth.','11',NULL,NULL),(10,'External congenital disease','Enter External congenital disease',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'Disability/defect to an External body organ in the body from the birth.','11',NULL,NULL),(11,'Pandemic','Enter Pandemic',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'Charges include owning to hospitalization due to novel corona virus.','13',NULL,NULL),(12,'Pre Hospitalization','Enter Pre Hospitalization',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'The expenses incurred by a insured person prior to hospitalization on a account of Doctor visit, \n                                   tests conducted or any other medical procedures undertaken are termed as pere hospitalization expenses. \n                                   Generally, policies cover expenses incurred for a duration of 30 to 60 days prior hospitalization.','5',NULL,NULL),(13,'Post Hospitalization','Enter Post Hospitalization',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'The expenses incurred after being discharged from the hospital on account of doctor visits, \n                                   Post-operative procedures, other medical procedure are termed as post hospitalization expenses. \n                                   Generally, Policies cover expenses incurred for a duration of 60 to 120 days after hospitalization.','5',NULL,NULL),(14,'Restore Benefit','Enter Restore Benefit',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'Under this benefit, if you consume the complete sum insured under a policy due to one or more \n                                   hospitalizations, then again you will be eligible to use the entire sum insured within the policy period.\n                                   For restoration to be implemented the admissible claim amount will be considered, If a person putrs a \n                                   claim and there are deductions that portion will be excluded from the restoration element.','14',NULL,NULL),(15,'Copay','',4,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'When you claim co-pay will be the amount which will be deducted from your admissible claim amount since \n                                   it\'s a policy condition. All insurance policies do not have a co pay condition. If a co pay condition \n                                   is present your policy it could applicable due on claims for certain ailments, Claims for dependents \n                                   parents or all members, claims for members above certain age  or not adhering to certain policy \n                                   conditions.','15',NULL,NULL),(16,'Copay Deduction In %','Enter Copay Deduction In %',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'','15',NULL,NULL),(17,'Remark','',2,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'','15',NULL,NULL),(18,'No claim Bonus','',4,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'When a policy renewed without lodging a claim, a benefit can be availed be the customer. This benefit could be \n                                   in the form of a discount in premium or increase in sum insured.','16',NULL,NULL),(19,'% Increase in Sum Insured','Enter % Increase in Sum Insured',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'','16',NULL,NULL),(20,'Discount Premium','Enter Discount Premium',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'','16',NULL,NULL),(21,'Organ Donar','',4,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'If a recipient of an organ has an insurance policy where organ donor expenses covered then the costs \n                                      incurred for hospitalization and procedure  for donor is also covered. Traditionally insurance \n                                      policies would cover the cost of a surgery of organ donation only for the policy holder. However \n                                      now it is possible to cover the hospitalization and surgery expenses of the donor also. Costs of \n                                      pre and post hospitalization costs of the donor and costs on account of post- surgery complication \n                                      are not generally not covered under insurance.','11',NULL,NULL),(22,'Organ Donor Value','Enter Organ Donor Value',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'','11',NULL,NULL),(23,'OPD Cover','',4,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'Out door patient treatment does not involve hospitalization. Here you meet a doctor  for consultaion \n                                   and are prescribed to take medicines or undergo tests or other medical procedure.','17',NULL,NULL),(24,'OPD Amount Payable','Enter OPD Amount Payable',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'','17',NULL,NULL),(25,'Maternity Cover','',4,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'Under this benefit a female who is covered under the policy can claim expenses incurred on account of \n                                   child birth during hospitalization upto the limit of the cover. In retail insurance policies waiting \n                                   period of 2 Years or more may apply on the coverage. Generally pre hospitalization and post hospitalization \n                                   expenses are not covered under the maternity benefit.','2',NULL,NULL),(26,'Maternity Waiting Period','Enter Maternity Waiting Period',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'','2',NULL,NULL),(27,'Normal delivery sum Insured','Enter Normal delivery sum Insured',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'','2',NULL,NULL),(28,'C Sec - sum insured','Enter C Sec - sum insured',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'Caesarean section, also known as C - Section, or Caesarean delivery, is the use of surgery to delivery, \n                                      is the use of surgery deliver babies. A caesarean section is often necessary when a vaginal delivery \n                                      would put the baby or mother at risk.','2',NULL,NULL),(29,'Baby Vaccination','',4,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'Under this benefit after child birth expenses incurred for vaccination which are prescribed as per \n                                   medical board are covered. The charges will have to be validated as per the guideline provided by \n                                   medical board.','2',NULL,NULL),(30,'Baby Vaccination Amount Payable','Enter Baby Vaccination Amount Payable',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'','2',NULL,NULL),(31,'New born baby cover','',4,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'When this cover is availed, the new born baby gets covered under the policy as an insured instantly \n                                   after birth without payment of additional premium.','2',NULL,NULL),(32,'Health Checkup','',4,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'Under this benefit the expenses upto the limit prescribed and for listed tests will be borne from \n                                   insurer. The common conditions for eligiability of health check-up are after one or more claim free \n                                   renewals you will be entitled for reimbursement of limited expenses some peoples offered annual \n                                   checkups, upto the defined limit you can go to the list or empaneled vendors and get yourself tested \n                                   for free as per the list of tests provided.','3',NULL,NULL),(33,'Initial waiting Period','Enter Initial waiting Period',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'','3',NULL,NULL),(34,'Health Checkup Amount Payable','Enter Health Checkup Amount Payable',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'','3',NULL,NULL),(35,'Emergency Ambulance','',4,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'','4',NULL,NULL),(36,'Emergency Ambulance Amount Payable','Enter Emergency Ambulance Amount Payable',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'','4',NULL,NULL),(37,'Domiciliary Hospitalization','',4,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'A situation when a person needs to be hospitalized but could not be due to non-availability of acommodation \n                                   in hospital or condition of patient didn\'t allow him to be shifted so he was treated at home. Some \n                                   policies cover domicilliary hospitalization but subject to conditions like the domicilliary treatment \n                                   should last for a particular period. Limits will be defined for the amount payable under domicilliary \n                                   treatment.','1',NULL,NULL),(38,'Domiciliary Hospitalization Value','Enter Domiciliary Hospitalization',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'','1',NULL,NULL),(39,'Ayurveda/Homeopathy','',4,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'Costs incurred for alternative medical treatments (Ayurveda/Yoga/Unani/Sidha/Homepathy) are payable \n                                   subject to admission in a registered hospital.','6',NULL,NULL),(40,'Ayurveda/Homeopathy Amount Payable','Enter Ayurveda/Homeopathy Amount Payable',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'','6',NULL,NULL),(41,'Eye Cover','',4,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'Damage to the eye to an accident or cataract treatment usually covered. Genric optician and spectacle \n                                   charges are not covered under mediclaim. Limits of cataract cover are defined under the policy costs \n                                   incurred due to congential eye defects may not be covered.','7',NULL,NULL),(42,'Eye Cover Amount Payable','Enter Eye Cover Amount Payable',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'','7',NULL,NULL),(43,'Dental Cover','',4,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'Costs incurred due to dental treatment arising due to an accident are covered under mediclaim insurance. \n                                   Some plans may offer costs incurred due to root canal or other such surgeries. Tooth extraction or \n                                   cosmatic Dental Treatment is not covered under mediclaim.','8',NULL,NULL),(44,'Dental Cover Amount Payable','Enter Dental Cover Amount Payable',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'','8',NULL,NULL),(45,'Critical illness Benefit','',4,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'This is a supplementary benefit where the patient after being diagnosed with a dreadful listed disease \n                                   has to survive a limited period (Mostly 30 days). Thereafter he/she is paid a lumpsum amount of \n                                   treatment as per his/her convenience. The list of diseases vary from company to company the most \n                                   common are cancer, Stroke, Heart attack, Coronary bypass surgery, Multiple organ failure etc..','9',NULL,NULL),(46,'Critical illness Amount Payable','Enter Critical illness Amount Payable',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'','9',NULL,NULL),(47,'Worldwide Emergency Cover','',4,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,1,NULL,'Under this benefit the insurance policy will cover expenses incurred overseas owing to a unforsean\n                                   health condition. Traditionally mediclaim insurance would not cover medical expenses if incurred \n                                   outside indian borders, However now some insurers offer this feature as an addon benefit.','10',NULL,NULL),(48,'Worldwide Emergency Amount Payable','Enter Worldwide Emergency Amount Payable',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'','10',NULL,NULL),(49,'Amount Deductible','Enter Amount Deductible',1,1,0,'2026-01-14 11:46:42','2026-01-14 11:46:42',NULL,0,NULL,'','10',NULL,NULL),(50,'Add Remarks','',5,1,0,'2